{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Cerivastatin, a statin sharing the dihydroxyheptenoic acid and 4-fluorophenyl pharmacophore, has absolute oral bioavailability of about 60% in humans, directly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "In a randomized crossover study in healthy young men, cerivastatin absolute bioavailability was 60% with 90% CI 51-70%, a robust high value above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Fluvastatin, the closest retrieved analogue, has absolute bioavailability reported as 0.29 in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Fluvastatin oral bioavailability was 24% in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Rosuvastatin absolute bioavailability is 20% in humans, meeting the threshold and supporting high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Brequinar, a low-similarity oral drug, shows >90% bioavailability, providing weak but supportive evidence that this chemotype can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Fluvastatin estimated bioavailability was 19% in one 10 mg oral dose study in healthy male volunteers, slightly below the threshold; this is a single borderline value for a different statin and does not outweigh the multiple higher fluvastatin and cerivastatin measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pitavastatin, a statin with the dihydroxyheptenoic acid and 4-fluorophenyl quinoline core. The closest statin analogues cerivastatin (60%), fluvastatin (mostly 24-30%), and rosuvastatin (20%) all meet or exceed the 20% threshold; no affirmative low-bioavailability evidence transfers strongly. Prediction: high.",
  "evidence_gaps": [
    "No direct pitavastatin bioavailability record is present in the retrieved evidence; the closest analogues are other statins with variable first-pass extraction.",
    "Fluvastatin has one borderline 19% value, but multiple higher values for the same compound reduce its weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

